//! Build script: embeds the application icon, the version information and the application
//! manifest (`assets/app.manifest`: DPI awareness, common controls 6, supported Windows versions,
//! long paths) into the executable, and writes the table of the vendored browser pages.
//!
//! `winresource` finds `rc.exe` of the Windows SDK through the registry, so nothing but cargo and
//! the MSVC build tools is needed. The icon itself is generated by `examples/make_icon.rs` and
//! kept in `assets/`.
//!
//! The browser pages (`../web/dist`, a production build of the Instagram clone's frontend that
//! `update-web.bat` makes; web brief 4.2) are embedded with `include_bytes!`: the table
//! `$OUT_DIR/web_files.rs` lists every file with its content type and an ETag, and
//! `src/web_assets.rs` includes it. The build fails with a sentence when the folder is missing,
//! when a file `../web/VENDORED.json` lists is missing or has another size, or when a file has a
//! type the server would not know how to serve. Node.js is never needed here.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

/// The content types of the files the vendored pages may hold, by extension.
const MIME_TYPES: [(&str, &str); 13] = [
    ("html", "text/html; charset=utf-8"),
    ("js", "text/javascript; charset=utf-8"),
    ("css", "text/css; charset=utf-8"),
    ("txt", "text/plain; charset=utf-8"),
    ("json", "application/json"),
    ("svg", "image/svg+xml"),
    ("png", "image/png"),
    ("jpg", "image/jpeg"),
    ("webp", "image/webp"),
    ("ico", "image/x-icon"),
    ("woff2", "font/woff2"),
    ("wasm", "application/wasm"),
    ("map", "application/json"),
];

/// FNV-1a, 64 bits (the same hash as `instagram_core::text::fnv1a_64`).
fn fnv1a_64(bytes: &[u8]) -> u64 {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

/// The files below `folder`, with their paths relative to it written with "/", sorted.
fn files_below(folder: &Path) -> Vec<(String, PathBuf)> {
    let mut found = Vec::new();
    let mut pending = vec![folder.to_path_buf()];
    while let Some(next) = pending.pop() {
        let entries = std::fs::read_dir(&next).unwrap_or_else(|error| panic!("The browser pages folder {} cannot be read: {error}", next.display()));
        for entry in entries {
            let path = entry.unwrap_or_else(|error| panic!("The browser pages folder {} cannot be read: {error}", next.display())).path();
            if path.is_dir() {
                pending.push(path);
            } else {
                let relative = path.strip_prefix(folder).unwrap_or(&path).to_string_lossy().replace('\\', "/");
                found.push((relative, path));
            }
        }
    }
    found.sort();
    found
}

/// Writes `$OUT_DIR/web_files.rs` from `../web/dist`.
fn embed_web_pages() {
    let manifest_dir = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap_or_default());
    let web = manifest_dir.join("..").join("web");
    let dist = web.join("dist");
    let vendored_file = web.join("VENDORED.json");
    println!("cargo:rerun-if-changed=../web/dist");
    println!("cargo:rerun-if-changed=../web/VENDORED.json");
    if !dist.join("index.html").is_file() {
        panic!("The browser pages are missing: {} has no index.html. Run update-web.bat (it needs Node.js) or restore web\\dist.", dist.display());
    }
    let vendored_text = std::fs::read_to_string(&vendored_file).unwrap_or_else(|error| panic!("{} cannot be read: {error}. Run update-web.bat.", vendored_file.display()));
    let vendored: serde_json::Value = serde_json::from_str(&vendored_text).unwrap_or_else(|error| panic!("{} is not valid JSON: {error}", vendored_file.display()));
    let listed = vendored.get("files").and_then(serde_json::Value::as_array).unwrap_or_else(|| panic!("{} has no \"files\" list.", vendored_file.display()));
    for file in listed {
        let path = file.get("path").and_then(serde_json::Value::as_str).unwrap_or_default();
        let bytes = file.get("bytes").and_then(serde_json::Value::as_u64).unwrap_or(u64::MAX);
        let on_disk = std::fs::metadata(dist.join(path)).map(|metadata| metadata.len()).unwrap_or_else(|_| panic!("web\\dist\\{path} is listed in web\\VENDORED.json but missing. Run update-web.bat."));
        if on_disk != bytes {
            panic!("web\\dist\\{path} has {on_disk} bytes, but web\\VENDORED.json says {bytes}. Run update-web.bat.");
        }
    }

    let mut table = String::from("/// The vendored browser pages (written by build.rs from web/dist).\npub static WEB_FILES: &[instagram_core::web::WebFile] = &[\n");
    for (relative, path) in files_below(&dist) {
        let extension = relative.rsplit_once('.').map(|(_, extension)| extension.to_ascii_lowercase()).unwrap_or_default();
        let content_type = MIME_TYPES.iter().find(|(known, _)| *known == extension).map(|(_, mime)| *mime).unwrap_or_else(|| panic!("web\\dist\\{relative} has a type the browser pages server does not serve (.{extension}); add it to MIME_TYPES in app\\build.rs or leave it out of the build."));
        let bytes = std::fs::read(&path).unwrap_or_else(|error| panic!("{} cannot be read: {error}", path.display()));
        let etag = format!("\"{:016x}\"", fnv1a_64(&bytes));
        let absolute = std::path::absolute(&path).unwrap_or(path.clone()).display().to_string();
        let _ = writeln!(
            table,
            "    instagram_core::web::WebFile {{ path: {relative:?}, content_type: {content_type:?}, etag: {etag:?}, immutable: {}, bytes: include_bytes!({absolute:?}) }},",
            relative.starts_with("assets/")
        );
    }
    table.push_str("];\n");
    let out = PathBuf::from(std::env::var("OUT_DIR").unwrap_or_default()).join("web_files.rs");
    std::fs::write(&out, table).unwrap_or_else(|error| panic!("{} cannot be written: {error}", out.display()));
}

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=assets/app.ico");
    println!("cargo:rerun-if-changed=assets/app.manifest");
    embed_web_pages();
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }
    let mut resource = winresource::WindowsResource::new();
    resource
        .set("ProductName", "Instagram Windows App")
        .set("FileDescription", "Instagram Windows App")
        .set("OriginalFilename", "instagram-windows-app.exe")
        .set("LegalCopyright", "Licensed under the Apache License, Version 2.0.")
        .set_manifest_file("assets/app.manifest");
    if std::path::Path::new("assets/app.ico").exists() {
        resource.set_icon("assets/app.ico");
    } else {
        // Only on a tree where the icon has not been generated yet.
        println!(
            "cargo:warning=assets/app.ico is missing: run `cargo run -p instagram-windows-app --example make_icon`."
        );
    }
    if let Err(error) = resource.compile() {
        panic!("The version resource could not be compiled: {error}");
    }
}
